#### Phase 1: Blue-Green Infrastructure (Week 1)

1. **Create S3 Buckets**

   ```bash
   # Blue environment (current production)
   aws s3 mb s3://gainwell-claims-blue

   # Green environment (new version staging)
   aws s3 mb s3://gainwell-claims-green

   # Enable versioning for rollback
   aws s3api put-bucket-versioning \
     --bucket gainwell-claims-blue \
     --versioning-configuration Status=Enabled
   ```

2. **Configure CloudFront Distribution**

   ```hcl
   # terraform/cloudfront.tf
   resource "aws_cloudfront_distribution" "claims_app" {
     enabled = true

     origin {
       domain_name = aws_s3_bucket.blue.bucket_regional_domain_name
       origin_id   = "blue"

       s3_origin_config {
         origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
       }
     }

     origin {
       domain_name = aws_s3_bucket.green.bucket_regional_domain_name
       origin_id   = "green"

       s3_origin_config {
         origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
       }
     }

     # Default to Blue (current production)
     default_cache_behavior {
       allowed_methods        = ["GET", "HEAD", "OPTIONS"]
       cached_methods         = ["GET", "HEAD"]
       target_origin_id       = "blue"
       viewer_protocol_policy = "redirect-to-https"

       forwarded_values {
         query_string = false
         cookies {
           forward = "none"
         }
       }
     }
   }
   ```

