#### Phase 3: Feature Flags (Week 3)

1. **LaunchDarkly Integration**

   ```typescript
   // src/featureFlags/launchDarkly.ts
   import { LDClient, initialize } from 'launchdarkly-js-client-sdk';

   const ldClient: LDClient = initialize(
     process.env.VITE_LAUNCHDARKLY_CLIENT_ID!,
     {
       key: 'anonymous', // Replace with user ID in production
       anonymous: true
     }
   );

   export async function isFeatureEnabled(flagKey: string): Promise<boolean> {
     await ldClient.waitForInitialization();
     return ldClient.variation(flagKey, false);
   }
   ```

2. **Feature Flag Usage**

   ```typescript
   // src/pages/ClaimsPage.tsx
   import { useEffect, useState } from 'react';
   import { isFeatureEnabled } from '../featureFlags/launchDarkly';

   function ClaimsPage() {
     const [newClaimsUIEnabled, setNewClaimsUIEnabled] = useState(false);

     useEffect(() => {
       isFeatureEnabled('new-claims-ui').then(setNewClaimsUIEnabled);
     }, []);

     return newClaimsUIEnabled ? (
       <NewClaimsUI />
     ) : (
       <LegacyClaimsUI />
     );
   }
   ```

